#!/usr/bin/env bash
# Creates the portal database roles (see roles.sql) as the bootstrap superuser, through the local socket of the postgres
# pod. Idempotent. The password comes from .tools/secrets/k3d-pg-portal-password (generated by up.sh) and travels
# through a mode-600 temporary file redirected inside the toolbox, never in an argument list or the output.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../../.." && pwd)"
cd "$ROOT"
readonly PASSWORD_FILE=.tools/secrets/k3d-pg-portal-password
[[ -s "$PASSWORD_FILE" ]] || { echo "missing $PASSWORD_FILE (run up.sh)" >&2; exit 1; }
umask 077
mkdir -p .tools/tmp
tmp=.tools/tmp/roles.sql
trap 'rm -f "$tmp"' EXIT
{
  printf "\\set portal_password '%s'\n" "$(<"$PASSWORD_FILE")"
  cat "$HERE/roles.sql"
} > "$tmp"
# ./tk allocates a TTY, so the file is redirected inside the toolbox shell instead of piped from here.
./tk sh -c "kubectl -n platform-db exec -i postgres-0 -- psql -v ON_ERROR_STOP=1 -q -U postgres_admin -d platform < $tmp"
echo "portal roles applied"
